<?php
namespace Tests\Feature;use Illuminate\Support\Facades\{Route,Schema};use Tests\TestCase;
class TransportSchedulingArchitectureTest extends TestCase{public function test_tran2_schema_is_normalized():void{foreach(['transport_schedules','transport_schedule_days','transport_calendar_exceptions','transport_services','transport_service_passengers','transport_service_changes','transport_alerts']as$table)$this->assertTrue(Schema::hasTable($table));$this->assertTrue(Schema::hasColumns('transport_services',['company_id','uuid','transport_route_id','scheduled_start_at','scheduled_arrival_at','planned_vehicle_id','planned_driver_id','passenger_snapshot_status','generation_source']));$this->assertTrue(Schema::hasColumn('transport_services','actual_start_at'));$this->assertTrue(Schema::hasColumn('transport_services','actual_arrival_at'));}public function test_tran2_routes_are_authenticated():void{$public=collect(Route::getRoutes())->filter(fn($route)=>str_starts_with($route->uri(),'transporte'))->filter(fn($route)=>!in_array('auth',$route->gatherMiddleware()));$this->assertCount(0,$public);}public function test_guest_cannot_open_daily_operation():void{$this->get('/transporte/operacion')->assertRedirect('/login');}}
